// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { LocateFixedIcon, SearchIcon } from 'lucide-react'
import type { ReactNode } from 'react'

import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import { BROKEN, CAPTIONS, FILTERS, GROUPS, LINKS, STATS, WORKING } from './script'

const ORDER = GROUPS.flatMap((group) =>
  LINKS.map((link, index) => ({ link, index })).filter(({ link }) => link.group === group.key),
)
const BROKEN_INDEX = LINKS.findIndex((link) => link.status >= 400)

const build: Build = ({
  tl,
  q,
  qa,
  pos,
  step,
  final,
  move,
  click,
  count,
  fly,
  type,
  wait,
  cursorOut,
}) => {
  const target = pos(`pl-${BROKEN_INDEX}`, 0, 0)
  tl.set(
    q('ring'),
    { x: target.x - 3, y: target.y - 2, width: target.w + 6, height: target.h + 4 },
    0,
  )

  step(0)
  tl.fromTo(
    qa('pl'),
    { backgroundColor: 'rgba(56,189,248,0)' },
    { backgroundColor: 'rgba(56,189,248,0.28)', duration: 0.2, stagger: 0.06 },
    0.3,
  )
  ;(['links', 'unique', 'external'] as const).forEach((key, index) =>
    count(`stat-${key}`, STATS[key], { at: index === 0 ? '<' : '<0.1', duration: 0.8 }),
  )

  step(1, '+=0.4')
  const seen = new Set<string>()
  ORDER.forEach(({ link, index }, order) => {
    const at = `step-1+=${(0.1 + order * 0.16).toFixed(2)}`
    const land = `step-1+=${(0.62 + order * 0.16).toFixed(2)}`
    fly(`dot-${index}`, `pl-${index}`, `row-${index}`, { at, duration: 0.55, lift: 24 })
    tl.to(q(`dot-${index}`), { opacity: 0, duration: 0.1 }, land)
    if (!seen.has(link.group)) {
      seen.add(link.group)
      tl.fromTo(q(`group-${link.group}`), { opacity: 0 }, { opacity: 1, duration: 0.2 }, land)
    }
    tl.fromTo(q(`row-${index}`), { opacity: 0, x: -6 }, { opacity: 1, x: 0, duration: 0.2 }, land)
  })
  tl.to(qa('pl'), { backgroundColor: 'rgba(56,189,248,0)', duration: 0.3 })

  step(2, '+=0.3')
  move('check')
  click('check')
  type('check-text', 'Checking…', { at: '<', speed: 0.02 })
  LINKS.forEach((link, index) => {
    if (!link.status) return
    tl.fromTo(
      q(`badge-${index}`),
      { opacity: 0, scale: 0.5 },
      { opacity: 1, scale: 1, duration: 0.2, ease: 'back.out(3)' },
      '<0.12',
    )
  })
  type('check-text', 'Check links', { speed: 0.02 })
  type('summary', `${BROKEN} broken · ${WORKING} working`, { at: '<' })

  step(3, '+=0.4')
  move('filter-0')
  click('filter-0')
  tl.to(
    q('filter-0'),
    {
      backgroundColor: 'rgba(251,113,133,0.2)',
      borderColor: 'rgba(251,113,133,0.6)',
      color: '#fda4af',
      duration: 0.2,
    },
    '<',
  )
  tl.to(
    [...qa('row').filter((row) => row !== q(`row-${BROKEN_INDEX}`)), ...qa('group')],
    { opacity: 0.15, duration: 0.3 },
    '<',
  )
  tl.to(q(`group-site`), { opacity: 1, duration: 0.3 }, '<')
  move('show', { at: '+=0.2' })
  click('show')
  tl.fromTo(
    q('ring'),
    { opacity: 0, scale: 1.6 },
    { opacity: 1, scale: 1, duration: 0.4, ease: 'power3.out' },
    '<',
  )
  tl.to(q(`pl-${BROKEN_INDEX}`), { backgroundColor: 'rgba(251,113,133,0.3)', duration: 0.2 }, '<')
  tl.to([...qa('row'), ...qa('group')], { opacity: 1, duration: 0.25 }, '+=0.25')
  tl.to(q('filter-0'), { opacity: 1, duration: 0.15 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

function A({ i, children }: { i: number; children: ReactNode }) {
  return (
    <span
      data-d={`pl pl-${i}`}
      className="rounded-sm text-[#2563eb] underline decoration-[#2563eb]/40"
    >
      {children}
    </span>
  )
}

function Page() {
  return (
    <div className="h-full bg-[#fafafa] text-[#111]">
      <div className="flex items-center gap-3 border-b border-black/5 px-4 py-2.5">
        <span className="flex items-center gap-1.5 text-[11px] font-semibold">
          <span className="size-3 rounded bg-[#111]" /> Northwind Docs
        </span>
        <span className="ml-auto flex gap-2.5 text-[9.5px] text-[#555]">
          {[0, 1, 2].map((i) => (
            <span key={i} data-d={`pl pl-${i}`} className="rounded-sm">
              {LINKS[i].text}
            </span>
          ))}
        </span>
      </div>
      <div className="space-y-2.5 px-4 pt-4 text-[9.5px] leading-relaxed text-[#444]">
        <h3 className="text-[16px] font-bold tracking-tight text-[#111]">Getting started</h3>
        <p>
          Start with the <A i={3}>Install</A> steps, then read the <A i={4}>API reference</A> for
          every endpoint.
        </p>
        <div className="h-12 rounded-lg bg-[#111] p-2 font-mono text-[8.5px] text-[#a5f3fc]">
          npm i northwind
        </div>
        <p>
          The source lives on <A i={5}>GitHub</A> and ships as an <A i={6}>npm package</A>.
        </p>
        <p>
          Upgrading from v1? The <A i={7}>Old setup guide</A> still covers it.
        </p>
        <p>
          Questions go to <A i={8}>support@northwind.app</A>.
        </p>
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Link Toolkit collecting a page’s links into groups, checking them and filtering to the broken one"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://docs.northwind.app/start"
        panelWidth={236}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="flex min-h-0 flex-1 flex-col gap-1.5 p-2">
              <div className="grid grid-cols-3 gap-1">
                {(
                  [
                    ['links', 'Links'],
                    ['unique', 'Unique URLs'],
                    ['external', 'External sites'],
                  ] as const
                ).map(([key, label]) => (
                  <div
                    key={key}
                    className="rounded-md border border-line bg-canvas/60 py-1 text-center"
                  >
                    <p
                      data-d={`stat-${key}`}
                      className="text-[12px] font-semibold tabular-nums text-ink"
                    >
                      0
                    </p>
                    <p className="text-[8px] text-muted">{label}</p>
                  </div>
                ))}
              </div>
              <div className="flex gap-1">
                <span className="flex h-6 min-w-0 flex-1 items-center gap-1 rounded-md border border-line bg-canvas/80 px-1.5 text-[9px] text-muted">
                  <SearchIcon className="size-2.5 shrink-0" />
                  <span className="truncate">Search link text or URL</span>
                </span>
                <span
                  data-d="check"
                  className="flex h-6 items-center rounded-md bg-[var(--accent)] px-2 text-[9px] font-medium text-canvas"
                >
                  <span data-d="check-text">Check links</span>
                </span>
              </div>
              <div className="flex gap-1 overflow-hidden">
                {FILTERS.slice(0, 4).map((filter, index) => (
                  <span
                    key={filter}
                    data-d={`filter-${index}`}
                    className="shrink-0 rounded-full border border-line px-1.5 py-0.5 text-[8.5px] text-ink-soft"
                  >
                    {filter}
                  </span>
                ))}
              </div>
              <p data-d="summary" className="h-3 text-[9px] text-ink-soft" />
              <div className="min-h-0 flex-1 space-y-1 overflow-hidden">
                {GROUPS.map((group) => {
                  const rows = ORDER.filter(({ link }) => link.group === group.key)
                  return (
                    <div key={group.key}>
                      <p
                        data-d={`group group-${group.key}`}
                        className="mb-0.5 text-[8.5px] font-medium uppercase tracking-wider text-muted opacity-0"
                      >
                        {group.label} · {rows.length}
                      </p>
                      {rows.map(({ link, index }) => (
                        <div
                          key={index}
                          data-d={`row row-${index}`}
                          className="flex h-[17px] items-center gap-1.5 rounded px-1 text-[9px] opacity-0"
                        >
                          <span className="min-w-0 flex-1 truncate text-ink-soft">{link.text}</span>
                          {index === BROKEN_INDEX ? (
                            <span data-d="show" className="text-muted">
                              <LocateFixedIcon className="size-2.5" />
                            </span>
                          ) : null}
                          {link.status ? (
                            <span
                              data-d={`badge-${index}`}
                              className="rounded px-1 font-mono text-[8px] opacity-0"
                              style={{
                                color: link.status >= 400 ? '#fb7185' : '#34d399',
                                backgroundColor:
                                  link.status >= 400
                                    ? 'rgba(251,113,133,0.12)'
                                    : 'rgba(52,211,153,0.12)',
                              }}
                            >
                              {link.status}
                            </span>
                          ) : null}
                        </div>
                      ))}
                    </div>
                  )
                })}
              </div>
            </div>
          </div>
        }
      >
        <Page />
      </BrowserChrome>
      {LINKS.map((_, index) => (
        <span
          key={index}
          data-d={`dot-${index}`}
          className="absolute left-0 top-0 z-30 size-2 rounded-full bg-[var(--accent)] opacity-0 shadow-[0_0_10px_var(--accent)]"
        />
      ))}
      <span
        data-d="ring"
        className="pointer-events-none absolute left-0 top-0 z-30 rounded-md border-2 border-[#fb7185] opacity-0"
      />
    </DemoStage>
  )
}
